import { ProofStrip, proofPlaceholders, type ProofLogo } from '@/components/site/ProofStrip'
import { cn } from '@/lib/cn'

// The site's proof section (v3/V3Proof): a White lead line (20/28) centered over the proof marquee, 40px apart, with
// the section's padding under it only (it follows a hero). Marks come through `logos` (Acme placeholders by default);
// the strip runs them twice per loop, as the site's V3Proof does, so each 68s pass moves two sets.
export interface ProofBlockProps {
  /** The line over the marks. */
  title?: string
  logos?: ProofLogo[]
  /** Names the heading (`<id>-title`). */
  id?: string
  className?: string
}

export function ProofBlock({ title = 'Trusted by teams and agents at', logos = proofPlaceholders, id = 'proof', className }: ProofBlockProps) {
  return (
    <section data-ds="proof-block" aria-labelledby={`${id}-title`} className={cn('pb-(--ds-layout-section) text-fg', className)}>
      <div className="mx-auto flex w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] flex-col items-center gap-10 px-(--ds-layout-gutter) text-center">
        <h2 id={`${id}-title`} className="max-w-(--ds-layout-measure) type-body-lg text-pretty text-fg">{title}</h2>
        <ProofStrip logos={[...logos, ...logos]} />
      </div>
    </section>
  )
}

export default ProofBlock

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
